const defaultLayout = { section_order: ["actions", "campaign", "catalog", "testimonials", "lead", "gallery", "address"], hidden_sections: [] as string[], cover_enabled: true, profile_position: "cover" as const, profile_shape: "circle" as const, text_align: "center" as const, button_style: "soft" as const, show_gallery: true, cover_treatment: "light" as const, logo_size: "medium" as const, logo_shape: "circle" as const, logo_fit: "contain" as const, cover_opacity: 55, cover_position_x: 50, cover_position_y: 50, logo_offset_x: 0, logo_offset_y: 0, logo_scale: 1, cover_scale: 100, title_color: "#0f172a", tagline_color: "#64748b", font_family: "Inter", title_font_size: 30, tagline_font_size: 14, section_spacing: "comfortable" as const, page_style: "clean" as const, background_effect: "solid" as const, hero_layout: "classic" as const, button_size: "medium" as const, button_shadow: true, button_text_color: "#263b3a", custom_button_text_color: "#FFFFFF", card_style: "soft" as const, gallery_layout: "floating" as const, gallery_radius: 22, gallery_gap: 12, gallery_background: "transparent", section_title_color: "#253d3e", body_text_color: "#718078", accent_color: "#91a08f", background_overlay: 55 };
