function Field({ label, children, hint }: { label: string; children: React.ReactNode; hint?: string }) { return <label className="block"><span className="mb-1.5 flex items-center justify-between text-xs font-bold text-white/75"><span>{label}</span>{hint && <small className="font-normal text-white/40">{hint}</small>}</span>{children}</label>; }
